navigate(event: MouseEvent, view: 'main' | 'about') {
  if (event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) return;
  event.preventDefault();
  this.view.set(view);
  globalThis.history.pushState(null, '', view === 'about' ? '/about' : '/');
}

