pub fn count(text: &str) -> Result<u32, String> {
    if text.len() > 4096 {
        return Err("Use text of at most 4096 bytes.".into());
    }
    u32::try_from(text.split_whitespace().count()).map_err(|_| "Too many words.".into())
}

