export const api: typeof Contract = {
  count(text) {
    if (utf8Length(text) > 4096) throw 'Use text of at most 4096 bytes.';
    let count = 0, inWord = false;
    for (const scalar of text) {
      const word = !whitespace(scalar);
      if (word && !inWord) count++;
      inWord = word;
    }
    return count;
  },
};

package export_examples_word_count_api

import (
	wit "go.bytecodealliance.org/pkg/wit/types"
	"strings"
)

func Count(text string) wit.Result[uint32, string] {
	if len(text) > 4096 {
		return wit.Err[uint32, string]("Use text of at most 4096 bytes.")
	}
	return wit.Ok[uint32, string](uint32(len(strings.Fields(text))))
}

#include "lsf/text.h"

bool exports_examples_word_count_api_count(probe_string_t *text, uint32_t *value,
                                           probe_string_t *error) {
    if (text->len > 4096) {
        probe_string_free(text);
        lsf_text_error(error, "Use text of at most 4096 bytes.");
        return false;
    }
    uint32_t count = 0;
    bool in_word = false;
    size_t offset = 0;
    while (offset < text->len) {
        bool word = !lsf_text_whitespace(lsf_text_next(text, &offset));
        if (word && !in_word) ++count;
        in_word = word;
    }
    probe_string_free(text);
    *value = count;
    return true;
}

public final class Capsule implements Bindings.Exports {
    public Result<Long, String> count(String text) {
        if (Text.utf8Length(text) > 4096) return Result.err("Use text of at most 4096 bytes.");
        long count = 0;
        boolean inside = false;
        for (int offset = 0; offset < text.length();) {
            int character = text.codePointAt(offset);
            boolean word = !Text.whitespace(character);
            if (word && !inside) count++;
            inside = word;
            offset += Character.charCount(character);
        }
        return Result.ok(count);
    }
}

public class ApiExportsImpl : IApiExports
{
    public static Result<uint, string> Count(string text)
    {
        if (Text.Utf8Length(text) > 4096) return Result<uint, string>.Err("Use text of at most 4096 bytes.");
        uint count = 0;
        bool inWord = false;
        foreach (char scalar in text) {
            bool word = !Text.Whitespace(scalar);
            if (word && !inWord) ++count;
            inWord = word;
        }
        return Result<uint, string>.Ok(count);
    }
}
